{"query": "-- TASK 3: Reassign customers 1,2,3 to Sarah Johnson (9) and 4,5,6 to Mike Chen (10)
UPDATE "Customer" SET "SupportRepId" = 9 WHERE "CustomerId" IN (1, 2, 3);
UPDATE "Customer" SET "SupportRepId" = 10 WHERE "CustomerId" IN (4, 5, 6);
SELECT "CustomerId", "SupportRepId" FROM "Customer" WHERE "CustomerId" IN (1,2,3,4,5,6) ORDER BY "CustomerId";"}
